// DETERMINISTIC LAYER 1 - PII scrubbing. Nothing reaches an LLM before this runs.
const results = [];
for (const item of $input.all()) {
  const b = item.json.body ?? item.json;
  const email = String(b.email ?? b.from ?? '').trim().toLowerCase();
  const subject = String(b.subject ?? '');
  const raw = String(b.message ?? b.text ?? b.description ?? b.body ?? '');
  const flags = [];
  let msg = raw;

  const rules = [
    ['PAN', /\b(?:\d[ -]?){15,18}\d\b/g],
    ['CVV', /\b(?:cvv|cvc|security\s*code)\D{0,10}\d{3,4}\b/gi],
    ['PIN', /\bpin\D{0,10}\d{4,6}\b/gi],
    ['SSN', /\b\d{3}-\d{2}-\d{4}\b/g],
    ['CARD_EXPIRY', /\b(?:exp(?:iry|ires|iration)?)\D{0,8}\d{2}\s*[\/-]\s*\d{2,4}\b/gi],
    ['ACCOUNT_NUMBER', /\b(?:acct|account|a\/c|routing)\s*(?:no\.?|number|#)?\s*[:#]?\s*\d{6,14}\b/gi],
    ['IBAN', /\b[A-Z]{2}\d{2}[A-Z0-9]{11,30}\b/g]
  ];

  for (const rule of rules) {
    const label = rule[0];
    const re = rule[1];
    if (re.test(msg)) { flags.push(label); }
    re.lastIndex = 0;
    msg = msg.replace(re, '[' + label + '_REDACTED]');
  }

  results.push({
    json: {
      ticket_id: 'VP-' + Date.now() + '-' + Math.floor(Math.random() * 10000),
      received_at: new Date().toISOString(),
      email,
      subject,
      message: msg,
      pii_detected: flags.length > 0,
      pii_types: flags,
      chars_removed: raw.length - msg.length
    }
  });
}
return results;

// DETERMINISTIC LAYER 2 - tier limits come from code, never from the model.
const TIERS = {
  standard: { dispute_credit_cap: 50, refund_cap: 35, overdraft_fee: 35, overdraft_max_per_day: 3,
    card_sla: '3-5 business days by standard mail; expedited shipping available for a 15 dollar fee',
    virtual_card: 'available on request for a 3 dollar fee',
    investigation_days: 10, provisional_credit: 'after 10 business days of investigation',
    refund_processing: '3-5 business days after approval', support_channel: 'standard email and chat queue' },
  gold: { dispute_credit_cap: 200, refund_cap: 75, overdraft_fee: 25, overdraft_max_per_day: 2,
    card_sla: '1-2 business days by expedited mail at no extra charge',
    virtual_card: 'issued automatically at no charge',
    investigation_days: 5, provisional_credit: 'after 5 business days of investigation',
    refund_processing: '1-2 business days after approval', support_channel: 'priority queue with callback service' },
  premium: { dispute_credit_cap: 500, refund_cap: 150, overdraft_fee: 0, overdraft_max_per_day: 0,
    card_sla: 'same business day by courier where available, next business day otherwise, no extra charge',
    virtual_card: 'issued automatically at no charge',
    investigation_days: 1, provisional_credit: 'within 24 hours of verified dispute submission',
    refund_processing: 'same business day if approved before 3:00 PM ET, next business day otherwise',
    support_channel: 'dedicated relationship manager and 24/7 priority hotline' }
};

const t = $('Sanitize PII').first().json;
const out = [];
for (const item of $input.all()) {
  const c = item.json.body ?? item.json;
  const rawTier = String(c.tier ?? c.account_tier ?? c.customer_tier ?? 'standard').toLowerCase().trim();
  const tier = TIERS[rawTier] ? rawTier : 'standard';
  const limits = TIERS[tier];
  const status = String(c.account_status ?? c.status ?? 'active').toLowerCase();
  const balance = Number(c.balance ?? c.current_balance ?? 0);

  out.push({ json: {
    ticket_id: t.ticket_id,
    received_at: t.received_at,
    email: t.email,
    subject: t.subject,
    message: t.message,
    pii_detected: t.pii_detected,
    pii_types: t.pii_types,
    customer_id: String(c.customer_id ?? c.id ?? ''),
    customer_name: String(c.name ?? c.full_name ?? ''),
    tier,
    tier_label: tier.charAt(0).toUpperCase() + tier.slice(1),
    account_status: status,
    balance,
    account_healthy: status === 'active' && balance >= 0,
    dispute_credit_cap: limits.dispute_credit_cap,
    refund_cap: limits.refund_cap,
    overdraft_fee: limits.overdraft_fee,
    overdraft_max_per_day: limits.overdraft_max_per_day,
    card_sla: limits.card_sla,
    virtual_card: limits.virtual_card,
    investigation_days: limits.investigation_days,
    provisional_credit: limits.provisional_credit,
    refund_processing: limits.refund_processing,
    support_channel: limits.support_channel,
    customer_raw: c
  } });
}
return out;

const t = $('Sanitize PII').first().json;
return [{ json: {
  ticket_id: t.ticket_id,
  email: t.email,
  status: 'ESCALATED',
  escalation_team: 'Tier 1 Support',
  escalation_reason: 'No VaultPay account matches the email on this ticket. Identity must be verified by a human agent.',
  customer_message: 'Thanks for contacting VaultPay. We could not match your email to an account, so a support specialist will take over and verify your identity before we can discuss account details.',
  automated: false
} }];

// Single escalation exit. Every deterministic guardrail and every QA failure lands here.
// The predecessor may be an HTTP node (card block/replace), whose output is the API
// response rather than the ticket. So resolve context from whichever guardrail ran.
const SOURCES = [
  'Enforce QA Verdict',
  'Dispute Guardrails',
  'Lost Card Triage',
  'Refund Guardrails',
  'Unclassified Intent',
  'Unknown Customer Escalation',
  'Build Tier Policy Context'
];

function lookup(name) {
  try {
    const j = $(name).first().json;
    return j && typeof j === 'object' ? j : null;
  } catch (e) {
    return null;
  }
}

let ctx = {};
for (const name of SOURCES) {
  const j = lookup(name);
  if (j && (j.ticket_id || j.escalation_reason)) { ctx = j; break; }
}

const actions = [];
if (lookup('Block Card (Fraud Dispute)')) { actions.push('card_blocked'); }
if (lookup('Block Card')) { actions.push('card_blocked'); }
if (lookup('Order Replacement Card')) { actions.push('replacement_card_ordered'); }

const out = [];
for (const item of $input.all()) {
  const d = (item.json && typeof item.json === 'object') ? item.json : {};
  const pick = (key) => {
    const v = d[key];
    if (v !== undefined && v !== null && v !== '') { return v; }
    const c = ctx[key];
    return (c === undefined) ? null : c;
  };

  const team = pick('escalation_team') || 'Tier 2 Support';
  const reason = pick('escalation_reason') || 'Policy requires human review for this request.';
  const customerMessage = pick('customer_message') || ('Thanks for contacting VaultPay. Your ticket needs a specialist to look at it personally, so I have passed it to our ' + team + ' team. They will be in touch shortly. Nothing further is needed from you right now.');

  out.push({ json: {
    ticket_id: pick('ticket_id'),
    status: 'ESCALATED_TO_HUMAN',
    escalated: true,
    escalation_team: team,
    escalation_reason: reason,
    tier: d.tier_label ?? d.tier ?? ctx.tier_label ?? ctx.tier ?? null,
    customer_id: pick('customer_id'),
    intent: pick('intent'),
    qa_risk: pick('qa_risk'),
    violations: d.violations ?? ctx.violations ?? [],
    actions_taken: actions,
    response: customerMessage
  } });
}
return out;

options.systemMessage:
=You are the VaultPay policy specialist. You answer customer policy questions using ONLY the VaultPay internal policy documents reachable through your knowledge base tools.

CUSTOMER CONTEXT (authoritative, retrieved live from the core banking system - never contradict it):
- Customer id: {{ $json.customer_id }}
- Tier: {{ $json.tier_label }}
- Account status: {{ $json.account_status }}
- Overdraft fee for this tier: {{ $json.overdraft_fee }} dollars per occurrence
- Card replacement SLA: {{ $json.card_sla }}
- Temporary virtual card: {{ $json.virtual_card }}
- Dispute investigation: {{ $json.investigation_days }} business days
- Support channel: {{ $json.support_channel }}

RULES
1. Always search the knowledge base tools before answering. Never answer from general banking knowledge or from the public internet.
2. If the policy documents do not cover the question, say so plainly and say a human agent will follow up. Do not invent a policy.
3. Answer for THIS customer tier only. Do not quote another tier unless the customer asks to compare.
4. You may explain fees, timelines and eligibility. You must NOT promise a refund, a fee waiver, a credit, or the outcome of any investigation.
5. Never state or repeat card numbers, PINs or account numbers. Redaction markers in the message stay redacted.
6. Write a finished customer-facing reply: warm, plain English, no internal document ids, no bullet dump. 120 words or fewer.
7. End by naming the exact policy area you relied on, for example: This is based on our overdraft policy.

