// DETERMINISTIC LAYER 3 - fraud detection and tier cap enforcement happen BEFORE the agent runs.
const out = [];
for (const item of $input.all()) {
  const d = item.json;
  const text = String(d.message ?? '').toLowerCase();

  const fraudTerms = ['unauthorised','unauthorized','fraud','fraudulent','did not make','didn\'t make','dont recognise','don\'t recognise','dont recognize','don\'t recognize','not recognise','not recognize','not mine','someone else','stolen','hacked','compromised','identity theft'];
  let fraud = false;
  for (const term of fraudTerms) { if (text.includes(term)) { fraud = true; } }

  const amounts = [];
  const re = /\$\s*([0-9]{1,3}(?:,[0-9]{3})*(?:\.[0-9]{1,2})?)/g;
  let m = re.exec(text);
  while (m) { amounts.push(Number(m[1].replace(/,/g, ''))); m = re.exec(text); }
  if (amounts.length === 0) {
    const re2 = /([0-9]{1,3}(?:,[0-9]{3})*(?:\.[0-9]{2}))\s*(?:dollars|usd)/g;
    let m2 = re2.exec(text);
    while (m2) { amounts.push(Number(m2[1].replace(/,/g, ''))); m2 = re2.exec(text); }
  }
  const amount = amounts.length ? Math.max.apply(null, amounts) : null;

  const cap = Number(d.dispute_credit_cap);
  const overCap = amount !== null && amount > cap;
  const suspended = d.account_status !== 'active';

  const reasons = [];
  if (fraud) { reasons.push('Unrecognised or unauthorised transaction - VP-DISP-004 requires immediate routing to Fraud Investigation and forbids conditional credit until fraud confirms the transaction was not made by the account holder.'); }
  if (overCap) { reasons.push('Disputed amount of ' + amount + ' dollars exceeds the ' + d.tier_label + ' conditional credit cap of ' + cap + ' dollars.'); }
  if (suspended) { reasons.push('Account status is ' + d.account_status + ' - human review required before any credit.'); }

  out.push({ json: Object.assign({}, d, {
    intent: 'TRANSACTION_DISPUTE',
    disputed_amount: amount,
    fraud_suspected: fraud,
    over_tier_cap: overCap,
    requires_human: fraud || overCap || suspended,
    escalation_team: fraud ? 'Fraud Investigation' : 'Tier 2 Support',
    escalation_reason: reasons.join(' '),
    allowed_credit: fraud ? 0 : Math.min(amount === null ? cap : amount, cap)
  }) });
}
return out;

