const out = [];
for (const item of $input.all()) {
  const d = item.json;
  const text = String(d.message ?? '').toLowerCase();

  const merchantTerms = ['merchant','store','shop','seller','vendor','retailer','amazon','netflix','spotify','uber','subscription','order never','never arrived','did not arrive','goods','purchase from'];
  let merchant = false;
  for (const term of merchantTerms) { if (text.includes(term)) { merchant = true; } }

  const feeTerms = ['overdraft fee','monthly fee','maintenance fee','transfer fee','service fee','bank fee','account fee'];
  let vaultpayFee = false;
  for (const term of feeTerms) { if (text.includes(term)) { vaultpayFee = true; } }

  const negligenceTerms = ['negligence','your staff','your agent lied','sued','lawyer','legal action','fraud by your','scammed me'];
  let negligence = false;
  for (const term of negligenceTerms) { if (text.includes(term)) { negligence = true; } }

  const amounts = [];
  const re = /\$\s*([0-9]{1,3}(?:,[0-9]{3})*(?:\.[0-9]{1,2})?)/g;
  let m = re.exec(text);
  while (m) { amounts.push(Number(m[1].replace(/,/g, ''))); m = re.exec(text); }
  const amount = amounts.length ? Math.max.apply(null, amounts) : null;

  const cap = Number(d.refund_cap);
  const overCap = amount !== null && amount > cap;
  const badStanding = d.account_status !== 'active' || Number(d.balance) < 0;

  const reasons = [];
  if (overCap) { reasons.push('Requested refund of ' + amount + ' dollars exceeds the ' + d.tier_label + ' automated approval cap of ' + cap + ' dollars - VP-REF-005 requires Tier 2 approval.'); }
  if (negligence) { reasons.push('Message contains language suggesting fraud or staff negligence - VP-REF-005 mandatory escalation trigger.'); }
  if (badStanding) { reasons.push('Account is suspended or overdrawn - VP-REF-005 forbids automated refund processing.'); }

  out.push({ json: Object.assign({}, d, {
    intent: 'REFUND_REQUEST',
    requested_amount: amount,
    merchant_charge: merchant && !vaultpayFee,
    vaultpay_fee: vaultpayFee,
    over_refund_cap: overCap,
    negligence_language: negligence,
    requires_human: overCap || negligence || badStanding,
    escalation_team: 'Tier 2 Support',
    escalation_reason: reasons.join(' '),
    allowed_refund: Math.min(amount === null ? cap : amount, cap)
  }) });
}
return out;

