// DETERMINISTIC LAYER 4 - the model advises, code decides. A hard phrase scan runs regardless of the verdict.
const FORBIDDEN = [
  'we will refund you','we will refund','your money is on its way','refund approved',
  "you'll receive your money back",'you will receive your money back','money back guaranteed',
  'i guarantee','we guarantee','guaranteed refund','rest assured you will get'
];
const PII = [/\b(?:\d[ -]?){15,18}\d\b/, /\bcvv\D{0,10}\d{3,4}\b/i, /\bpin\D{0,10}\d{4,6}\b/i];

const out = [];
for (const item of $input.all()) {
  const ctx = $('Collect Draft Reply').item.json;
  const raw = item.json.output ?? item.json;
  const verdict = typeof raw === 'string' ? JSON.parse(raw) : raw;

  const draft = String(ctx.draft ?? '');
  const lower = draft.toLowerCase();

  const hardViolations = [];
  for (const phrase of FORBIDDEN) {
    if (lower.includes(phrase)) { hardViolations.push('Forbidden guarantee phrase in draft: "' + phrase + '"'); }
  }
  for (const re of PII) {
    if (re.test(draft)) { hardViolations.push('Draft contains unredacted financial identifiers.'); }
  }
  if (!draft.trim()) { hardViolations.push('Draft reply was empty.'); }

  const modelViolations = Array.isArray(verdict.violations) ? verdict.violations : [];
  const approved = verdict.approved === true && hardViolations.length === 0;

  out.push({ json: {
    ticket_id: ctx.ticket_id,
    customer_id: ctx.customer_id,
    tier: ctx.tier_label,
    intent: ctx.intent ?? null,
    qa_approved: approved,
    qa_risk: hardViolations.length ? 'high' : (verdict.risk ?? 'low'),
    qa_reasoning: verdict.reasoning ?? '',
    violations: hardViolations.concat(modelViolations),
    final_response: approved ? draft : String(verdict.revised_response ?? draft),
    escalation_team: 'Tier 2 Support',
    escalation_reason: approved ? '' : 'Draft failed the automated QA guardrail: ' + hardViolations.concat(modelViolations).join(' | ')
  } });
}
return out;
